<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $items = sd_dashboard_nav_items(); ?><aside class="sd-dashboard-sidebar" aria-label="<?php esc_attr_e( 'Dashboard navigation', 'social-discovery' ); ?>"><div class="sd-dashboard-user"><img src="<?php echo esc_url( sd_avatar( get_current_user_id(), 48 ) ); ?>" alt=""><strong><?php echo esc_html( wp_get_current_user()->display_name ); ?></strong></div><nav><?php foreach ( $items as $key => $item ) : ?><a class="<?php echo 'dashboard' === $key ? 'is-active' : ''; ?>" href="<?php echo esc_url( $item[1] ); ?>"><?php echo esc_html( $item[0] ); ?></a><?php endforeach; ?></nav><a class="sd-dashboard-logout" href="<?php echo esc_url( sd_auth_logout_url() ); ?>"><?php esc_html_e( 'Log out', 'social-discovery' ); ?></a></aside>
